contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint dummy) public payable {
        require(dummy < 2 ** 200);
        require(address(c).balance < 100);

        uint balBefore = address(c).balance;

        bool reverted;
        c.getFirstWithdrawalBonus(address(c)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == balBefore);
    }
}

