// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy < 2 ** 200);
        vm.assume(address(c).balance < 100);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.getFirstWithdrawalBonus(address(c)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
